[8430]=[=[{o="Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.",n={{"Warsong Gulch Mark of Honor",3}},k=false}]=],
[8436]=[=[{o="Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",n={{"Arathi Basin Mark of Honor",3}},d="Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, <name>!",p="You've come back with news from Arathi, <class>?",c="Securing our resources in Arathi is an important task! You've done well, <name>.",r={m=4500,rep={{510,100}}},k=true}]=],
[8437]=[=[{o="Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",n={{"Arathi Basin Mark of Honor",3}},d="Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, <name>!",p="You've come back with news from Arathi, <class>?",c="Securing our resources in Arathi is an important task! You've done well, <name>.",r={m=7000,rep={{510,100}}},k=true}]=],
[8438]=[=[{o="Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds.",n={{"Arathi Basin Mark of Honor",3}},d="Our conflict with the Alliance has escalated to a true war.  No longer are false pretenses to enter into battle used or expected by either side at this point.\n\nThe battle for the Arathi Basin is one of resources, plain and simple.  Either the Alliance gets the resources and uses them against us or we get them and use them to keep our war efforts going.  Help the Defilers maintain the flow of resources we need, <name>!",p="You've come back with news from Arathi, <class>?",c="Securing our resources in Arathi is an important task! You've done well, <name>.",r={m=9000,rep={{510,100}}},k=true}]=],
