[8697]=[=[{o="Bring 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus.  You must also attain Honored reputation with Cenarion Circle to complete this quest.",n={{"Obsidian Idol",2},{"Silver Scarab",5},{"Bone Scarab",5}},d="The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, <class>.",p="Did you bring me the ring and materials, <name>?",c="I will swap the gem on the ring for you. You'll find the effect is much more... agreeable.",r={it={{21411,1,"Ring of Infinite Wisdom",4,"inv_jewelry_ring_ahnqiraj_03"}}},k=true}]=],
