[8705]=[=[{o="Bring 1 Qiraji Ornate Hilt, 2  Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus.  You must also attain Exalted reputation with Cenarion Circle to complete this quest.",n={{"Lambent Idol",2},{"Bronze Scarab",5},{"Ivory Scarab",5}},d="The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.",p="Did you bring me the components I require, <name>?",c="You've done well, <class>. This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, <name>. Wield it with great confidence and vanquish our enemies!",r={it={{21410,1,"Gavel of Infinite Wisdom",4,"inv_mace22"}}},k=true}]=],
